CREATE OR REPLACE SEMANTIC VIEW MULTIAGENT_DEMO.BENCH.SPEND_BASE_SV
  TABLES (t AS MULTIAGENT_DEMO.BENCH.INVENTORY PRIMARY KEY (snapshot_id) COMMENT = 'Spend fact table')
  FACTS (
    t.spend_amount AS inventory_value
  )
  DIMENSIONS (
    t.snapshot_date AS snapshot_date WITH SYNONYMS = ('date') COMMENT = 'Spend period date',
    t.product_id AS product_id WITH SYNONYMS = ('product', 'part number') COMMENT = 'Part number',
    t.plant AS plant WITH SYNONYMS = ('site') COMMENT = 'Plant',
    t.i_plant_attr_00 AS i_plant_attr_00 WITH SYNONYMS = ('plant', 'plant code') COMMENT = 'Spend attribute i_plant_attr_00. Represents the plant classification used by the Spend reporting team for slicing KPIs. Values are conformed against the enterprise master data hub, refreshed nightly, and may be blank for legacy records created before the 2019 ERP migration. Use for grouping and filtering only; do not aggregate.',
