CREATE OR REPLACE AGENT MULTIAGENT_DEMO.BENCH.SPEND_AGENT
  FROM SPECIFICATION $$
models:
  orchestration: claude-sonnet-4-6
instructions:
  response: "Be concise. Return the result table and a chart when the answer has more than one row."
tools:
  - tool_spec:
      type: cortex_analyst_text_to_sql
      name: query_spend_agg
      description: "Spend agg metrics by product, plant, date"
  - tool_spec:
      type: cortex_analyst_text_to_sql
      name: query_spend_base
      description: "Spend base metrics by product, plant, date"
  - tool_spec:
      type: data_to_chart
      name: data_to_chart
      description: "Generate a chart from query results"
tool_resources:
  query_spend_agg:
    semantic_view: MULTIAGENT_DEMO.BENCH.SPEND_AGG_SV
    execution_environment:
      type: warehouse
      warehouse: COMPUTE_WH
  query_spend_base:
    semantic_view: MULTIAGENT_DEMO.BENCH.SPEND_BASE_SV
    execution_environment:
      type: warehouse
      warehouse: COMPUTE_WH
$$;

CREATE OR REPLACE SEMANTIC VIEW MULTIAGENT_DEMO.BENCH.SAVINGS_AGG_SV
