  FACTS (
    t.savings_amount AS inventory_value
  )
  DIMENSIONS (
    t.snapshot_date AS snapshot_date WITH SYNONYMS = ('date') COMMENT = 'Savings period date',
    t.product_id AS product_id WITH SYNONYMS = ('product', 'part number') COMMENT = 'Part number',
