CREATE OR REPLACE SEMANTIC VIEW MULTIAGENT_DEMO.BENCH.SUPPLIER_RISK_BASE_SV
  TABLES (t AS MULTIAGENT_DEMO.BENCH.INVENTORY PRIMARY KEY (snapshot_id) COMMENT = 'Supplier Risk fact table')
  FACTS (
    t.supplier_risk_amount AS inventory_value
  )
  DIMENSIONS (
    t.snapshot_date AS snapshot_date WITH SYNONYMS = ('date') COMMENT = 'Supplier_Risk period date',
    t.product_id AS product_id WITH SYNONYMS = ('product', 'part number') COMMENT = 'Part number',
    t.plant AS plant WITH SYNONYMS = ('site') COMMENT = 'Plant',
    t.i_plant_attr_00 AS i_plant_attr_00 WITH SYNONYMS = ('plant', 'plant code') COMMENT = 'Supplier Risk attribute i_plant_attr_00. Represents the plant classification used by the Supplier Risk reporting team for slicing KPIs. Values are conformed against the enterprise master data hub, refreshed nightly, and may be blank for legacy records created before the 2019 ERP migration. Use for grouping and filtering only; do not aggregate.',
