CREATE OR REPLACE AGENT MULTIAGENT_DEMO.BENCH.SUPPLIER_RISK_AGENT
  FROM SPECIFICATION $$
models:
  orchestration: claude-sonnet-4-6
instructions:
  response: "Be concise. Return the result table and a chart when the answer has more than one row."
tools:
  - tool_spec:
      type: cortex_analyst_text_to_sql
      name: query_supplier_risk_agg
      description: "Supplier Risk agg metrics by product, plant, date"
  - tool_spec:
      type: cortex_analyst_text_to_sql
      name: query_supplier_risk_base
      description: "Supplier Risk base metrics by product, plant, date"
  - tool_spec:
      type: data_to_chart
      name: data_to_chart
      description: "Generate a chart from query results"
tool_resources:
  query_supplier_risk_agg:
    semantic_view: MULTIAGENT_DEMO.BENCH.SUPPLIER_RISK_AGG_SV
    execution_environment:
      type: warehouse
      warehouse: COMPUTE_WH
  query_supplier_risk_base:
    semantic_view: MULTIAGENT_DEMO.BENCH.SUPPLIER_RISK_BASE_SV
    execution_environment:
      type: warehouse
      warehouse: COMPUTE_WH
$$;

