CREATE OR REPLACE SEMANTIC VIEW MULTIAGENT_DEMO.BENCH.PRICING_BASE_SV
  TABLES (t AS MULTIAGENT_DEMO.BENCH.INVENTORY PRIMARY KEY (snapshot_id) COMMENT = 'Pricing fact table')
  FACTS (
    t.pricing_amount AS inventory_value
  )
  DIMENSIONS (
    t.snapshot_date AS snapshot_date WITH SYNONYMS = ('date') COMMENT = 'Pricing period date',
    t.product_id AS product_id WITH SYNONYMS = ('product', 'part number') COMMENT = 'Part number',
    t.plant AS plant WITH SYNONYMS = ('site') COMMENT = 'Plant',
