CREATE OR REPLACE AGENT MULTIAGENT_DEMO.BENCH.PRICING_AGENT
  FROM SPECIFICATION $$
models:
  orchestration: claude-sonnet-4-6
instructions:
  response: "Be concise. Return the result table and a chart when the answer has more than one row."
tools:
  - tool_spec:
      type: cortex_analyst_text_to_sql
      name: query_pricing_agg
      description: "Pricing agg metrics by product, plant, date"
  - tool_spec:
      type: cortex_analyst_text_to_sql
      name: query_pricing_base
      description: "Pricing base metrics by product, plant, date"
  - tool_spec:
      type: data_to_chart
      name: data_to_chart
      description: "Generate a chart from query results"
tool_resources:
  query_pricing_agg:
    semantic_view: MULTIAGENT_DEMO.BENCH.PRICING_AGG_SV
    execution_environment:
      type: warehouse
      warehouse: COMPUTE_WH
  query_pricing_base:
    semantic_view: MULTIAGENT_DEMO.BENCH.PRICING_BASE_SV
    execution_environment:
      type: warehouse
      warehouse: COMPUTE_WH
$$;

