CREATE OR REPLACE AGENT MULTIAGENT_DEMO.BENCH.QUALITY_AGENT
  FROM SPECIFICATION $$
models:
  orchestration: claude-sonnet-4-6
instructions:
  response: "Be concise. Return the result table and a chart when the answer has more than one row."
tools:
  - tool_spec:
      type: cortex_analyst_text_to_sql
      name: query_quality_agg
      description: "Quality agg metrics by product, plant, date"
  - tool_spec:
      type: cortex_analyst_text_to_sql
      name: query_quality_base
      description: "Quality base metrics by product, plant, date"
  - tool_spec:
      type: data_to_chart
      name: data_to_chart
      description: "Generate a chart from query results"
tool_resources:
  query_quality_agg:
    semantic_view: MULTIAGENT_DEMO.BENCH.QUALITY_AGG_SV
    execution_environment:
      type: warehouse
      warehouse: COMPUTE_WH
  query_quality_base:
    semantic_view: MULTIAGENT_DEMO.BENCH.QUALITY_BASE_SV
    execution_environment:
      type: warehouse
      warehouse: COMPUTE_WH
$$;

CREATE OR REPLACE SEMANTIC VIEW MULTIAGENT_DEMO.BENCH.LOGISTICS_AGG_SV
  TABLES (t AS MULTIAGENT_DEMO.BENCH.INVENTORY PRIMARY KEY (snapshot_id) COMMENT = 'Logistics fact table')
  FACTS (
    t.logistics_amount AS inventory_value
  )
  DIMENSIONS (
    t.snapshot_date AS snapshot_date WITH SYNONYMS = ('date') COMMENT = 'Logistics period date',
    t.product_id AS product_id WITH SYNONYMS = ('product', 'part number') COMMENT = 'Part number',
