CREATE OR REPLACE SEMANTIC VIEW MULTIAGENT_DEMO.BENCH.LOGISTICS_BASE_SV
  TABLES (t AS MULTIAGENT_DEMO.BENCH.INVENTORY PRIMARY KEY (snapshot_id) COMMENT = 'Logistics fact table')
  FACTS (
    t.logistics_amount AS inventory_value
  )
  DIMENSIONS (
    t.snapshot_date AS snapshot_date WITH SYNONYMS = ('date') COMMENT = 'Logistics period date',
    t.product_id AS product_id WITH SYNONYMS = ('product', 'part number') COMMENT = 'Part number',
    t.plant AS plant WITH SYNONYMS = ('site') COMMENT = 'Plant',
    t.i_plant_attr_00 AS i_plant_attr_00 WITH SYNONYMS = ('plant', 'plant code') COMMENT = 'Logistics attribute i_plant_attr_00. Represents the plant classification used by the Logistics reporting team for slicing KPIs. Values are conformed against the enterprise master data hub, refreshed nightly, and may be blank for legacy records created before the 2019 ERP migration. Use for grouping and filtering only; do not aggregate.',
