CREATE OR REPLACE SEMANTIC VIEW MULTIAGENT_DEMO.BENCH.WARRANTY_BASE_SV
  TABLES (t AS MULTIAGENT_DEMO.BENCH.INVENTORY PRIMARY KEY (snapshot_id) COMMENT = 'Warranty fact table')
  FACTS (
    t.warranty_amount AS inventory_value
  )
  DIMENSIONS (
    t.snapshot_date AS snapshot_date WITH SYNONYMS = ('date') COMMENT = 'Warranty period date',
    t.product_id AS product_id WITH SYNONYMS = ('product', 'part number') COMMENT = 'Part number',
    t.plant AS plant WITH SYNONYMS = ('site') COMMENT = 'Plant',
