CREATE OR REPLACE AGENT MULTIAGENT_DEMO.BENCH.WARRANTY_AGENT
  FROM SPECIFICATION $$
models:
  orchestration: claude-sonnet-4-6
instructions:
  response: "Be concise. Return the result table and a chart when the answer has more than one row."
tools:
  - tool_spec:
      type: cortex_analyst_text_to_sql
      name: query_warranty_agg
      description: "Warranty agg metrics by product, plant, date"
  - tool_spec:
      type: cortex_analyst_text_to_sql
      name: query_warranty_base
      description: "Warranty base metrics by product, plant, date"
  - tool_spec:
      type: data_to_chart
      name: data_to_chart
      description: "Generate a chart from query results"
tool_resources:
  query_warranty_agg:
    semantic_view: MULTIAGENT_DEMO.BENCH.WARRANTY_AGG_SV
    execution_environment:
      type: warehouse
      warehouse: COMPUTE_WH
  query_warranty_base:
