  METRICS (
    t.total_capex_amount AS SUM(t.capex_amount) COMMENT = 'Total capex amount',
    t.capex_record_count AS COUNT(t.snapshot_id) COMMENT = 'Number of capex records'
  )
  COMMENT = 'Capex semantic view for the A2A benchmark';

CREATE OR REPLACE SEMANTIC VIEW MULTIAGENT_DEMO.BENCH.CAPEX_BASE_SV
  TABLES (t AS MULTIAGENT_DEMO.BENCH.INVENTORY PRIMARY KEY (snapshot_id) COMMENT = 'Capex fact table')
  FACTS (
    t.capex_amount AS inventory_value
  )
  DIMENSIONS (
    t.snapshot_date AS snapshot_date WITH SYNONYMS = ('date') COMMENT = 'Capex period date',
