CREATE OR REPLACE AGENT MULTIAGENT_DEMO.BENCH.FORECAST_AGENT
  FROM SPECIFICATION $$
models:
  orchestration: claude-sonnet-4-6
instructions:
  response: "Be concise. Return the result table and a chart when the answer has more than one row."
tools:
  - tool_spec:
      type: cortex_analyst_text_to_sql
      name: query_forecast_agg
      description: "Forecast agg metrics by product, plant, date"
  - tool_spec:
      type: cortex_analyst_text_to_sql
      name: query_forecast_base
      description: "Forecast base metrics by product, plant, date"
  - tool_spec:
      type: data_to_chart
      name: data_to_chart
      description: "Generate a chart from query results"
tool_resources:
  query_forecast_agg:
    semantic_view: MULTIAGENT_DEMO.BENCH.FORECAST_AGG_SV
    execution_environment:
      type: warehouse
      warehouse: COMPUTE_WH
  query_forecast_base:
    semantic_view: MULTIAGENT_DEMO.BENCH.FORECAST_BASE_SV
    execution_environment:
      type: warehouse
      warehouse: COMPUTE_WH
$$;

CREATE OR REPLACE SEMANTIC VIEW MULTIAGENT_DEMO.BENCH.PRODUCTION_AGG_SV
