CREATE OR REPLACE SEMANTIC VIEW MULTIAGENT_DEMO.BENCH.PRODUCTION_BASE_SV
  TABLES (t AS MULTIAGENT_DEMO.BENCH.INVENTORY PRIMARY KEY (snapshot_id) COMMENT = 'Production fact table')
  FACTS (
    t.production_amount AS inventory_value
  )
