    t.i_warehouse_zone_attr_118 AS i_warehouse_zone_attr_118 WITH SYNONYMS = ('warehouse zone', 'warehouse_zone code') COMMENT = 'Procurement attribute i_warehouse_zone_attr_118. Represents the warehouse zone classification used by the Procurement reporting team for slicing KPIs. Values are conformed against the enterprise master data hub, refreshed nightly, and may be blank for legacy records created before the 2019 ERP migration. Use for grouping and filtering only; do not aggregate.',
    t.i_lot_class_attr_119 AS i_lot_class_attr_119 WITH SYNONYMS = ('lot class', 'lot_class code') COMMENT = 'Procurement attribute i_lot_class_attr_119. Represents the lot class classification used by the Procurement reporting team for slicing KPIs. Values are conformed against the enterprise master data hub, refreshed nightly, and may be blank for legacy records created before the 2019 ERP migration. Use for grouping and filtering only; do not aggregate.'
  )
  METRICS (
    t.total_procurement_amount AS SUM(t.procurement_amount) COMMENT = 'Total procurement amount',
    t.procurement_record_count AS COUNT(t.snapshot_id) COMMENT = 'Number of procurement records'
  )
  COMMENT = 'Procurement semantic view for the A2A benchmark';

